@import url("https://fonts.googleapis.com/css2?family=Figtree:wght@400..700&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Geist+Mono:wght@400;500&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Paddock: the front desk of a small clinic, scheduling the day. A cool,
  near-white canvas holds white surfaces drawn by one cool 0.0625rem border, with
  no drop at rest; only floating panels (menus, dialogs) carry a faint shadow.
  Inks are cool slate. The action is a calm deep teal, a solid fill with a
  crisp 0.0625rem highlight along its top edge. Visit status has its own hues:
  booked is a teal outline, arrived sky blue, in room violet, done slate grey
  and late coral red. Shapes are small rounded rectangles; only avatars and
  status dots are round. Figtree at compact sizes, tabular figures for times.

  The finish lives in tokens, so the `.dark` block flips every recipe at
  once: --primary-face is the teal fill's edge and highlight, --card-ring and
  --card-lift the bordered surface at rest and on hover, --track the recessed
  segmented well and --segment-lift the segment that sits in it.
*/

:root {
  /* ─── Surfaces: cool canvas, white surfaces with a cool border ─── */
  --background: oklch(0.985 0.004 220);
  --foreground: oklch(0.24 0.02 245);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.24 0.02 245);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.24 0.02 245);

  /* ─── The action: calm deep teal ─── */
  --primary: oklch(0.48 0.09 195);
  --primary-foreground: oklch(1 0 0);
  --primary-text: oklch(0.45 0.09 198);            /* links and the current day */

  --secondary: oklch(0.96 0.006 230);              /* the quiet tag chip */
  --secondary-foreground: oklch(0.38 0.02 245);
  --muted: oklch(0.965 0.006 225);                 /* wells: schedule columns, side panels */
  --muted-foreground: oklch(0.5 0.02 245);         /* 4.9:1 on a well */
  --accent: oklch(0.955 0.01 215);                 /* hover rows, the active nav item */
  --accent-foreground: oklch(0.24 0.02 245);

  --destructive: oklch(0.55 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --success: oklch(0.56 0.12 160);
  --warning: oklch(0.79 0.14 85);
  --info: oklch(0.6 0.12 235);

  --border: oklch(0.915 0.008 230);                /* the 0.0625rem cool line round every surface */
  --input: oklch(0.86 0.01 230);
  --ring: oklch(0.55 0.09 195 / 0.6);              /* the teal focus outline */

  /* ─── Visit status: one hue for each step of the visit ─── */
  --status-booked: oklch(0.48 0.09 195);
  --status-booked-text: oklch(0.42 0.08 198);
  --status-arrived: oklch(0.64 0.12 235);
  --status-arrived-text: oklch(0.45 0.12 240);
  --status-in-room: oklch(0.56 0.16 295);
  --status-in-room-text: oklch(0.46 0.16 295);
  --status-done: oklch(0.62 0.02 245);
  --status-done-text: oklch(0.42 0.02 245);
  --status-late: oklch(0.64 0.17 25);
  --status-late-text: oklch(0.5 0.17 25);
  --status-late-foreground: oklch(1 0 0);
  --arrived-fill: oklch(0.5 0.12 240);             /* the accent Button: deep enough for white text */
  --card-hover: oklch(0.99 0.003 220);
  --scrim: oklch(0.24 0.02 245 / 0.32);
  --track: oklch(0.945 0.008 230);                 /* the segmented control's recessed track */
  /* ─── Status text on a tinted badge: deep in its own hue ─── */
  --success-text: oklch(0.44 0.1 160);
  --warning-text: oklch(0.48 0.1 75);
  --destructive-text: oklch(0.49 0.18 25);
  --info-text: oklch(0.45 0.12 240);
  --field: oklch(1 0 0);

  /* ─── Shadows: flat, a 0.0625rem cool border; a faint drop on floating panels only ─── */
  --primary-face:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.2),
    0 0 0 0.0625rem oklch(0.42 0.085 198),
    0 0.0625rem 0.125rem oklch(0.3 0.05 210 / 0.14);
  --arrived-face:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.2),
    0 0 0 0.0625rem oklch(0.44 0.12 242),
    0 0.0625rem 0.125rem oklch(0.3 0.06 240 / 0.14);
  --card-ring:
    0 0 0 0.0625rem oklch(0.915 0.008 230);
  --card-lift:
    0 0 0 0.0625rem oklch(0.85 0.012 230);
  --card-focus:
    0 0 0 0.125rem oklch(0.55 0.09 195 / 0.55);
  --plate-ring:
    0 0 0 0.0625rem oklch(0.93 0.008 230);
  /* The edge of an empty field, checkbox, radio or off switch: a cool slate
     line at 3:1 against white, so the control's boundary stays visible. */
  --control-ring:
    0 0 0 0.0625rem oklch(0.62 0.02 245);
  --control-lift:
    0 0 0 0.0625rem oklch(0.5 0.02 245);
  --track-inset:
    inset 0 0 0 0.0625rem oklch(0.91 0.008 230);
  --menu-lift:
    0 0 0 0.0625rem oklch(0.9 0.008 230),
    0 0.25rem 0.75rem -0.125rem oklch(0.3 0.03 240 / 0.1);
  --primary-halo:
    0 0 0 0.1875rem oklch(0.55 0.09 195 / 0.14);
  --segment-lift:
    0 0 0 0.0625rem oklch(0.9 0.008 230),
    0 0.0625rem 0.0625rem oklch(0.3 0.03 240 / 0.06);

  /* ─── Type ─── */
  --font-sans: "Figtree", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* ─── Radius: small rounded rectangles that grow a little with the surface ─── */
  --radius: 0.5rem;
  --radius-xs: 0.25rem;    /* checkbox box, thin bars */
  --radius-sm: 0.375rem;   /* chips, badges, segments, menu rows */
  --radius-md: 0.5rem;     /* buttons, fields, nav items */
  --radius-lg: 0.5rem;     /* popovers, list rows, textareas */
  --radius-xl: 0.625rem;   /* cards and appointment slots */
  --radius-2xl: 0.625rem;  /* schedule columns, the timeline */
  --radius-3xl: 0.75rem;   /* the window, dialogs, sheets */

  /* ─── Motion: the standard product profile ─── */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  --shadow-xs: 0 0.0625rem 0.0625rem oklch(0.3 0.03 240 / 0.05);
  --shadow-sm: var(--card-ring);
  --shadow-md: var(--menu-lift);
  --shadow-lg: 0 0 0 0.0625rem oklch(0.9 0.008 230), 0 0.5rem 1.5rem -0.5rem oklch(0.3 0.03 240 / 0.14);
  --shadow-card: var(--card-ring);
  --shadow-menu: var(--menu-lift);
  --shadow-overlay: 0 0 0 0.0625rem oklch(0.9 0.008 230), 0 1rem 2.5rem -0.75rem oklch(0.24 0.02 245 / 0.22);
  --shadow-thumb: 0 0 0 0.0625rem oklch(0.62 0.02 245), 0 0.0625rem 0.125rem oklch(0.3 0.03 240 / 0.12);

  --chart-1: oklch(0.48 0.09 195);
  --chart-2: oklch(0.64 0.12 235);
  --chart-3: oklch(0.56 0.16 295);
  --chart-4: oklch(0.64 0.17 25);
  --chart-5: oklch(0.62 0.02 245);

  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/*
  Dark: the same schedule on a late shift. A cool slate canvas, surfaces one
  step lighter, a light teal action with dark text. Borders become faint
  light lines and the status hues lift so they keep their contrast.
*/
.dark {
  --background: oklch(0.185 0.012 240);
  --foreground: oklch(0.95 0.006 230);
  --card: oklch(0.22 0.012 240);
  --card-foreground: oklch(0.95 0.006 230);
  --popover: oklch(0.24 0.012 240);
  --popover-foreground: oklch(0.95 0.006 230);

  --primary: oklch(0.74 0.1 190);
  --primary-foreground: oklch(0.2 0.02 220);
  --primary-text: oklch(0.8 0.09 190);

  --secondary: oklch(0.27 0.012 240);
  --secondary-foreground: oklch(0.86 0.008 230);
  --muted: oklch(0.205 0.012 240);
  --muted-foreground: oklch(0.71 0.012 235);
  --accent: oklch(0.28 0.014 235);
  --accent-foreground: oklch(0.95 0.006 230);

  --destructive: oklch(0.67 0.17 25);
  --destructive-foreground: oklch(0.185 0.012 240);
  --success: oklch(0.72 0.13 160);
  --warning: oklch(0.82 0.13 85);
  --info: oklch(0.74 0.11 235);

  --border: oklch(1 0 0 / 0.09);
  --input: oklch(1 0 0 / 0.18);
  --ring: oklch(0.74 0.1 190 / 0.6);

  --status-booked: oklch(0.74 0.1 190);
  --status-booked-text: oklch(0.86 0.08 190);
  --status-arrived: oklch(0.74 0.11 235);
  --status-arrived-text: oklch(0.87 0.07 235);
  --status-in-room: oklch(0.72 0.13 295);
  --status-in-room-text: oklch(0.87 0.08 295);
  --status-done: oklch(0.66 0.015 240);
  --status-done-text: oklch(0.85 0.01 240);
  --status-late: oklch(0.7 0.15 25);
  --status-late-text: oklch(0.87 0.09 25);
  --status-late-foreground: oklch(0.185 0.012 240);
  --arrived-fill: oklch(0.74 0.11 235);
  --card-hover: oklch(0.25 0.012 240);
  --scrim: oklch(0 0 0 / 0.55);
  --track: oklch(0.155 0.012 240);
  --success-text: oklch(0.87 0.1 160);
  --warning-text: oklch(0.87 0.1 85);
  --destructive-text: oklch(0.87 0.09 25);
  --info-text: oklch(0.87 0.07 235);
  --field: oklch(0.22 0.012 240);

  --primary-face:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.28),
    0 0 0 0.0625rem oklch(0.66 0.1 190),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3);
  --arrived-face:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.28),
    0 0 0 0.0625rem oklch(0.66 0.11 235),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.3);
  --card-ring:
    0 0 0 0.0625rem oklch(1 0 0 / 0.09);
  --card-lift:
    0 0 0 0.0625rem oklch(1 0 0 / 0.16);
  --card-focus:
    0 0 0 0.125rem oklch(0.74 0.1 190 / 0.55);
  --plate-ring:
    0 0 0 0.0625rem oklch(1 0 0 / 0.06);
  --control-ring:
    0 0 0 0.0625rem oklch(0.56 0.012 240);
  --control-lift:
    0 0 0 0.0625rem oklch(0.66 0.012 240);
  --track-inset:
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.05);
  --menu-lift:
    0 0 0 0.0625rem oklch(1 0 0 / 0.1),
    0 0.25rem 0.75rem -0.125rem oklch(0 0 0 / 0.45);
  --primary-halo:
    0 0 0 0.1875rem oklch(0.74 0.1 190 / 0.2);
  --segment-lift:
    0 0 0 0.0625rem oklch(1 0 0 / 0.1),
    0 0.0625rem 0.0625rem oklch(0 0 0 / 0.3);

  --shadow-xs: 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.3);
  --shadow-lg: 0 0 0 0.0625rem oklch(1 0 0 / 0.1), 0 0.5rem 1.5rem -0.5rem oklch(0 0 0 / 0.5);
  --shadow-overlay: 0 0 0 0.0625rem oklch(1 0 0 / 0.1), 0 1rem 2.5rem -0.75rem oklch(0 0 0 / 0.6);
  --shadow-thumb: 0 0 0 0.0625rem oklch(0.56 0.012 240), 0 0.0625rem 0.125rem oklch(0 0 0 / 0.4);

  --chart-1: oklch(0.74 0.1 190);
  --chart-2: oklch(0.74 0.11 235);
  --chart-3: oklch(0.72 0.13 295);
  --chart-4: oklch(0.7 0.15 25);
  --chart-5: oklch(0.66 0.015 240);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary-text: var(--primary-text);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-status-booked: var(--status-booked);
  --color-status-arrived: var(--status-arrived);
  --color-status-in-room: var(--status-in-room);
  --color-status-done: var(--status-done);
  --color-status-late: var(--status-late);
  --color-status-late-foreground: var(--status-late-foreground);
  --color-arrived-fill: var(--arrived-fill);
  --color-card-hover: var(--card-hover);
  --color-scrim: var(--scrim);
  --color-track: var(--track);
  --color-field: var(--field);
  --color-success-text: var(--success-text);
  --color-warning-text: var(--warning-text);
  --color-destructive-text: var(--destructive-text);
  --color-info-text: var(--info-text);
  --color-status-booked-text: var(--status-booked-text);
  --color-status-arrived-text: var(--status-arrived-text);
  --color-status-in-room-text: var(--status-in-room-text);
  --color-status-done-text: var(--status-done-text);
  --color-status-late-text: var(--status-late-text);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  /* Compact desk sizes: slot titles and nav, then notes and times. */
  --text-ui: 0.875rem;
  --text-ui--line-height: 1.25rem;
  --text-note: 0.75rem;
  --text-note--line-height: 1rem;

  --radius-xs: var(--radius-xs);
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-2xl: var(--radius-2xl);
  --radius-3xl: var(--radius-3xl);

  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-card: var(--shadow-card);
  --shadow-menu: var(--shadow-menu);
  --shadow-overlay: var(--shadow-overlay);
  --shadow-thumb: var(--shadow-thumb);
  /* Named finishes the components use. */
  --shadow-primary-face: var(--primary-face);
  --shadow-arrived-face: var(--arrived-face);
  --shadow-card-ring: var(--card-ring);
  --shadow-card-lift: var(--card-lift);
  --shadow-card-focus: var(--card-focus);
  --shadow-plate: var(--plate-ring);
  --shadow-track-inset: var(--track-inset);
  --shadow-primary-halo: var(--primary-halo);
  --shadow-segment-lift: var(--segment-lift);
}

@layer base {
  * {
    @apply border-border outline-ring;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-sans);
    font-size: 0.875rem;
    font-weight: 400;
    line-height: 1.45;
    text-wrap: pretty;
  }

  /* Headings: semibold Figtree, a little tight, never display-size tracking. */
  :is(h1, h2) {
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.015em;
  }
  :is(h3, h4) {
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: -0.005em;
  }

  code, kbd, pre, samp {
    font-family: var(--font-mono);
    letter-spacing: 0;
  }

  td, th, time, data, output {
    font-variant-numeric: tabular-nums;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: compact;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 46);
  --layout-inset: calc(var(--spacing, 0.25rem) * 4);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 6);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 3);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 4);
}

